function label(options:{value:string;label:string}[],value:string){return options.find(o=>o.value===value)?.label||value}
</script>
<template><el-descriptions :column="2" border><el-descriptions-item label="工号">{{employee.code}}</el-descriptions-item><el-descriptions-item label="姓名">{{employee.name}}</el-descriptions-item><el-descriptions-item label="联系电话">{{employee.phone||'—'}}</el-descriptions-item><el-descriptions-item label="人员类型">{{label(personnelTypes,employee.personnel_type)}}</el-descriptions-item><el-descriptions-item label="状态">{{label(employeeStatuses,employee.status)}}</el-descriptions-item><el-descriptions-item label="公司">{{employee.company_name||'—'}}</el-descriptions-item><el-descriptions-item label="组织">{{employee.org_unit_name||'—'}}</el-descriptions-item><el-descriptions-item label="岗位">{{employee.position_name||'—'}}</el-descriptions-item><el-descriptions-item label="直属上级">{{employee.manager_name||'—'}}</el-descriptions-item><el-descriptions-item label="入职日期">{{employee.hire_date||'—'}}</el-descriptions-item></el-descriptions><h2>任职历史</h2><el-table :data="employee.assignments||[]" empty-text="暂无任职记录"><el-table-column prop="org_unit_name" label="组织"/><el-table-column prop="position_name" label="岗位"/><el-table-column prop="manager_name" label="直属上级"/><el-table-column prop="effective_from" label="开始日期"/><el-table-column prop="effective_to" label="结束日期"/></el-table><h2>人事异动</h2><el-table :data="employee.events||[]" empty-text="暂无异动记录"><el-table-column label="类型"><template #default="{row}">{{label(eventKinds,row.kind)}}</template></el-table-column><el-table-column prop="effective_date" label="生效日期"/><el-table-column prop="reason" label="原因"/><el-table-column prop="handover_notes" label="交接说明"/></el-table></template>
